import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.vLhlLNVn.js";const o="/images/designer-regions.svg",_=JSON.parse('{"title":"设计器区域与操作","description":"","frontmatter":{},"headers":[],"relativePath":"guide/designer-tour.md","filePath":"guide/designer-tour.md"}'),i={name:"guide/designer-tour.md"};function s(n,t,c,l,u,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="设计器区域与操作" tabindex="-1">设计器区域与操作 <a class="header-anchor" href="#设计器区域与操作" aria-label="Permalink to &quot;设计器区域与操作&quot;">​</a></h1><p>以下导览基于默认配置的设计器界面；各区域可通过 <code>ui</code> 选项调整或关闭。挂载后默认打开内置欢迎模板：横向 A4（297 × 210 mm）单页海报，含 30 个演示元素与一个页面模板，可直接选中编辑试用。正式制作模板时，从菜单「文件 → 新建文档」（或代码 <code>studio.document.create()</code>）开始空白文档。</p><p><img src="'+o+'" alt="设计器区域示意：菜单栏、工具选项栏、工具栏、画布、页面与图层面板、属性面板和信息栏"></p><table tabindex="0"><thead><tr><th>区域</th><th>用途</th></tr></thead><tbody><tr><td>菜单栏</td><td>按「文件 / 编辑 / 页面 / 排版 / 数据 / 视图 / 导出 / 帮助」分组的命令菜单，涵盖新建与保存文档、撤销重做、页面设置、打印预览、打印与导出</td></tr><tr><td>工具栏</td><td>选择工具、抓手平移工具，以及每种内置元素的创建工具；选中创建工具后在画布点击或拖拽创建元素</td></tr><tr><td>工具选项栏</td><td>随当前工具变化的编辑选项</td></tr><tr><td>画布与标尺</td><td>页面是打印范围，页面外区域用于编辑；标尺显示毫米刻度，可从标尺拖出参考线；画布可平移与缩放，缩放不改变物理打印尺寸</td></tr><tr><td>页面 / 图层面板</td><td>切换页面；查看元素列表、叠放顺序、显隐与锁定</td></tr><tr><td>属性面板</td><td>修改选中元素的位置、尺寸、旋转、不透明度、内容与绑定</td></tr><tr><td>元素设置</td><td>单个元素的独立属性弹窗，字段与属性面板一致</td></tr><tr><td>信息栏</td><td>查看坐标、选区尺寸、页码与缩放比例</td></tr></tbody></table><h2 id="从选中到修改" tabindex="-1">从选中到修改 <a class="header-anchor" href="#从选中到修改" aria-label="Permalink to &quot;从选中到修改&quot;">​</a></h2><p>用选择工具单击元素，画布出现选择框，属性面板随之显示该元素的可编辑字段。修改内容、字号或位置后画布即时更新；位置与宽高单位是 mm，字号单位是 pt。发生编辑后文档进入未保存状态（<code>studio.document.dirty</code> 为 <code>true</code>），保存成功后复位。</p><h2 id="从模板到输出" tabindex="-1">从模板到输出 <a class="header-anchor" href="#从模板到输出" aria-label="Permalink to &quot;从模板到输出&quot;">​</a></h2><ul><li>画布中的绑定变量以标签展示（如 <span><code>{{ customer.name }}</code></span>），编辑不影响表达式本身。</li><li>「文件 → 打印预览」打开打印预览：查看注入打印数据后的输出效果与绑定告警，可在对话框内调整输入数据。</li><li>「文件 → 打印」调起浏览器打印对话框；「导出 → 导出 HTML / 导出 PDF」生成输出文件。</li><li>打印数据只参与本次输出，不会把模板中的表达式永久替换掉。</li></ul>',8)])])}const p=e(i,[["render",s]]);export{_ as __pageData,p as default};
